// `traite` et `page` sont tous deux obligatoires : une page de Bavli ne s'identifie
// pas autrement. Aucun défaut — servir l'inventaire d'une page arbitraire
// tromperait l'appelant en silence.
//
// `segment_num` est optionnel : l'API l'expose pour restreindre à un segment.
//
// Aucune normalisation de casse : le match est strict côté API, et normaliser
// masquerait un 404 légitime — le seul signal disant à l'appelant que sa
// référence est fausse.
const input = $input.first().json;
const query = input.query || {};

const traite = (query.traite || '').trim();
const page = (query.page || '').trim();
const segment = (query.segment_num ?? '').toString().trim();

const manquants = [];
if (!traite) manquants.push('traite');
if (!page) manquants.push('page');
if (manquants.length) {
  return [{ json: { valide: false, erreur: {
    code: 400,
    message: 'Paramètre(s) requis : ' + manquants.join(', ')
           + ' (ex. ?traite=Berakhot&page=2a)',
    status: 'BAD_REQUEST'
  } } }];
}

return [{ json: {
  valide: true, traite: traite, page: page,
  segment_num: segment || null,
  requete: segment ? '?segment_num=' + encodeURIComponent(segment) : ''
} }];

// --- Désencapsulation de l'erreur HTTP -------------------------------------
// Avec onError: continueRegularOutput, un HTTP Request en échec ne produit PAS
// {statusCode, body} mais l'objet d'erreur axios : statusCode est absent, et le
// statut réel est enfoui dans le message sous la forme « 404 - {"detail":…} ».
// Sans ce traitement, le code retombe sur 200, la branche succès s'exécute sur
// un objet d'erreur, et l'appelant reçoit soit un faux succès vide, soit un 500
// (« Invalid status code: ERR_BAD_REQUEST » — error.code d'axios n'est pas un
// entier). Même problème et même parade que Normalize Error de DOC - Render PDF.
function lireErreur(item) {
  let brut = '';
  for (const c of [item?.error?.message, item?.message, item?.error?.description,
                   typeof item?.error === 'string' ? item.error : null]) {
    if (c) { brut = String(c); break; }
  }
  const m = brut.match(/^\s*(\d{3})\s*-\s*/);
  const statut = m ? parseInt(m[1], 10) : null;

  let detail = null;
  const i = brut.indexOf('{'), j = brut.lastIndexOf('}');
  if (i >= 0 && j > i) {
    const bloc = brut.slice(i, j + 1);
    for (const essai of [bloc, bloc.replace(/\\"/g, '"').replace(/\\\\/g, '\\')]) {
      try {
        const o = JSON.parse(essai);
        detail = o.detail || o?.error?.message || o.message || null;
        break;
      } catch (e) { /* essai suivant */ }
    }
  }
  return { statut, detail, brut };
}

const input = $input.first().json;
const params = $('Lire Paramètres').first().json;

const estErreur = input?.error !== undefined || input?.statusCode === undefined;

if (estErreur) {
  const e = lireErreur(input);
  const code = e.statut || 502;
  return [{
    json: {
      success: false,
      traite: params.traite,
      page: params.page,
      error: {
        code: code,
        message: e.detail || e.brut || "L'API n'a pas répondu",
        status: code === 404 ? 'PAGE_NOT_FOUND' : 'API_ERROR'
      }
    }
  }];
}

const data = input.body || input;
const liste = data.commentators || [];

// Proxy 1:1 : les clés `commentator` sont celles du filtre ?commentators= et ne
// doivent subir aucune réécriture.
return [{
  json: {
    success: true,
    traite: data.traite || params.traite,
    page: data.page || params.page,
    segment_num: data.segment_num ?? params.segment_num,
    corpus: data.corpus ?? null,
    count: data.count ?? liste.length,
    total_commentaries: data.total_commentaries ?? null,
    commentators: liste
  }
}];
